        "tool_name": "place_supplier_order",
        "parameters": {
            "po_id": "PO-38BF9C55"
        }
    },
    {
        "tool_name": "pay_supplier",
        "parameters": {
            "po_id": "PO-38BF9C55",
            "amount_cents": 677025
        }
    },
    {
        "tool_name": "post_journal_entry",
        "parameters": {
            "po_id": "PO-38BF9C55",
            "amount_cents": 677025
        }
    }
]

